### 1.4 Python 实现代码

在 `/Users/henry/.claude/skills/xhs-topic-analyzer/scripts/` 目录下创建新文件 `push_html.py`:

```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
HTML 格式微信推送 (V2.0 - 美化版)
"""
import requests
import json
from datetime import datetime
from pathlib import Path


def generate_html_template(notes, github_url=""):
    """生成 HTML 推送内容"""

    # 统计数据
    total_notes = len(notes)
    avg_likes = sum(n['likes'] for n in notes) // total_notes if total_notes > 0 else 0
    avg_collects = sum(n['collects'] for n in notes) // total_notes if total_notes > 0 else 0

    # TOP 10 笔记卡片
    note_cards = ""
    for i, note in enumerate(notes[:10], 1):
        title = note['title']
        likes = format_number(note['likes'])
        collects = format_number(note['collects'])
        comments = format_number(note['comments'])
        author = note['author']
        url = note['url']

        note_cards += f"""
        <div class="note-card">
            <span class="note-rank">{i}</span>
            <div class="note-title">{title}</div>
            <div class="note-meta">
                <span class="meta-item">❤️ {likes}</span>
                <span class="meta-item">⭐ {collects}</span>
                <span class="meta-item">💬 {comments}</span>
                <span class="meta-item">@{author}</span>
            </div>
            <a href="{url}" class="note-link">📱 查看笔记</a>
        </div>
        """

    # 亮点分析
    insights = f"""
    <div class="insight-item">
        <div class="insight-title">🏆 最高爆款指数</div>
        <div>{notes[0]['title'][:50]}...</div>
        <div style="margin-top:8px;color:#667eea;font-weight:700;">
            {format_number(notes[0]['likes'])} 赞 | {format_number(notes[0]['collects'])} 收藏
        </div>
    </div>

    <div class="insight-item">
        <div class="insight-title">📈 平均数据表现</div>
        <div>点赞: {format_number(avg_likes)} | 收藏: {format_number(avg_collects)}</div>
    </div>
    """

    # 完整 HTML
    html_template = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8">
        <style>
            body {{ font-family: -apple-system, sans-serif; line-height: 1.6; }}
            .container {{ max-width: 600px; margin: 0 auto; }}
            .header {{ background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); 
                     color: #fff; padding: 24px; text-align: center; }}
            .header h1 {{ margin: 0; font-size: 24px; }}
            .stats {{ display: flex; padding: 16px; background: #f8f9fa; }}
            .stat-item {{ flex: 1; text-align: center; }}
            .stat-number {{ font-size: 20px; font-weight: 700; color: #667eea; }}
            .note-card {{ padding: 20px; border-bottom: 1px solid #e9ecef; }}
            .note-rank {{ display: inline-block; background: #667eea; color: #fff; 
                         width: 28px; height: 28px; line-height: 28px; text-align: center; 
                         border-radius: 50%; margin-right: 8px; }}
            .note-title {{ font-size: 18px; font-weight: 600; margin: 12px 0; }}
            .note-meta {{ display: flex; gap: 12px; font-size: 14px; color: #6c757d; }}
            .note-link {{ display: inline-block; margin-top: 12px; padding: 8px 16px; 
                        background: #667eea; color: #fff; text-decoration: none; 
                        border-radius: 6px; }}
            .insights {{ padding: 24px; background: #f8f9fa; }}
            .insight-item {{ margin-bottom: 16px; padding: 16px; background: #fff; 
                           border-radius: 8px; border-left: 4px solid #667eea; }}
            .footer {{ padding: 20px; text-align: center; font-size: 12px; color: #6c757d; }}
        </style>
    </head>
    <body>
        <div class="container">
            <div class="header">
                <h1>📊 小红书财经爆文日报</h1>
                <div>📅 {datetime.now().strftime("%Y-%m-%d")} | 筛选: 点赞≥2000</div>
            </div>

            <div class="stats">
                <div class="stat-item">
                    <div class="stat-number">{total_notes}</div>
                    <div>发现爆文</div>
                </div>
                <div class="stat-item">
                    <div class="stat-number">{format_number(avg_likes)}</div>
                    <div>平均点赞</div>
                </div>
                <div class="stat-item">
                    <div class="stat-number">{format_number(avg_collects)}</div>
                    <div>平均收藏</div>
                </div>
            </div>

            {note_cards}

            <div class="insights">
                <h3>💡 选题亮点</h3>
                {insights}
            </div>

            <div class="footer">
                <p>📅 更新时间: {datetime.now().strftime("%H:%M:%S")}</p>
                {f'<p>🔗 查看完整报告: <a href="{github_url}">GitHub Pages</a></p>' if github_url else ''}
            </div>
        </div>
    </body>
    </html>
    """

    return html_template


def format_number(num):
    """格式化数字"""
    try:
        num = int(num)
    except (ValueError, TypeError):
        num = 0
    if num >= 10000:
        return f"{num/10000:.1f}万"
    return str(num)


def push_html_to_wechat(token, notes, github_url=""):
    """推送 HTML 格式到微信"""
    html_content = generate_html_template(notes, github_url)

    today = datetime.now().strftime("%m-%d")
    title = f"💰 小红书财经爆文日报 {today}"

    url = 'http://www.pushplus.plus/send'
    data = {
        "token": token,
        "title": title,
        "content": html_content,
        "template": "html"  # 使用 HTML 模板
    }

    try:
        response = requests.post(url, json=data, timeout=30)
        result = response.json()
        if result.get("code") == 200:
            print("[Success] HTML 推送成功！")
            return True
        else:
            print(f"[Failed] {result.get('msg')}")
            return False
    except Exception as e:
        print(f"[Error] {e}")
        return False


if __name__ == "__main__":
    # 测试代码
    test_notes = [
        {
            "title": "测试笔记标题",
            "likes": 5000,
            "collects": 2000,
            "comments": 500,
            "author": "测试博主",
            "url": "https://www.xiaohongshu.com/explore/123456"
        }
    ]

    token = "your_token_here"
    push_html_to_wechat(token, test_notes)
```

