### 2.5 JavaScript 交互

```javascript
// docs/assets/js/app.js

class ViralNotesApp {
    constructor() {
        this.notes = [];
        this.filteredNotes = [];
        this.currentSort = 'likes';
        this.init();
    }

    async init() {
        await this.loadData();
        this.setupEventListeners();
        this.render();
    }

    async loadData() {
        try {
            const response = await fetch('data/viral-notes.json');
            this.notes = await response.json();
            this.filteredNotes = [...this.notes];

            // 更新统计信息
            this.updateStats();

        } catch (error) {
            console.error('加载数据失败:', error);
            this.showError();
        }
    }

    updateStats() {
        const totalNotes = this.notes.length;
        const avgLikes = this.calculateAverage('likes');
        const avgCollects = this.calculateAverage('collects');
        const avgComments = this.calculateAverage('comments');

        document.getElementById('totalNotes').textContent = totalNotes;
        document.getElementById('avgLikes').textContent = this.formatNumber(avgLikes);
        document.getElementById('avgCollects').textContent = this.formatNumber(avgCollects);
        document.getElementById('avgComments').textContent = this.formatNumber(avgComments);

        // 更新时间
        const updateTime = new Date().toLocaleString('zh-CN');
        document.getElementById('updateTime').textContent = updateTime;
    }

    calculateAverage(field) {
        if (this.notes.length === 0) return 0;
        const sum = this.notes.reduce((acc, note) => acc + (note[field] || 0), 0);
        return Math.round(sum / this.notes.length);
    }

    formatNumber(num) {
        if (num >= 10000) {
            return (num / 10000).toFixed(1) + '万';
        }
        return num.toString();
    }

    setupEventListeners() {
        // 搜索
        const searchInput = document.getElementById('searchInput');
        searchInput.addEventListener('input', (e) => {
            this.filterNotes(e.target.value);
        });

        // 排序按钮
        const filterBtns = document.querySelectorAll('.filter-btn');
        filterBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                filterBtns.forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                this.currentSort = btn.dataset.sort;
                this.sortNotes();
            });
        });
    }

    filterNotes(keyword) {
        if (!keyword) {
            this.filteredNotes = [...this.notes];
        } else {
            keyword = keyword.toLowerCase();
            this.filteredNotes = this.notes.filter(note => 
                note.title.toLowerCase().includes(keyword) ||
                note.author.toLowerCase().includes(keyword)
            );
        }
        this.sortNotes();
    }

    sortNotes() {
        this.filteredNotes.sort((a, b) => b[this.currentSort] - a[this.currentSort]);
        this.renderNotes();
    }

    render() {
        this.renderNotes();
        this.renderInsights();
        document.getElementById('loading').style.display = 'none';
    }

    renderNotes() {
        const grid = document.getElementById('notesGrid');
        const emptyState = document.getElementById('emptyState');

        if (this.filteredNotes.length === 0) {
            grid.innerHTML = '';
            emptyState.style.display = 'block';
            return;
        }

        emptyState.style.display = 'none';
        grid.innerHTML = this.filteredNotes.map((note, index) => `
            <div class="note-card" onclick="window.open('${note.url}', '_blank')">
                <div class="note-header">
                    <span class="note-rank">${index + 1}</span>
                </div>
                <h3 class="note-title">${note.title}</h3>
                <p class="note-author">@${note.author}</p>
                <div class="note-stats">
                    <span class="stat-item">❤️ ${this.formatNumber(note.likes)}</span>
                    <span class="stat-item">⭐ ${this.formatNumber(note.collects)}</span>
                    <span class="stat-item">💬 ${this.formatNumber(note.comments)}</span>
                </div>
                <a href="${note.url}" class="note-link" onclick="event.stopPropagation()">查看笔记 →</a>
            </div>
        `).join('');
    }

    renderInsights() {
        // 热门选题
        const hotTopics = this.analyzeHotTopics();
        document.getElementById('hotTopics').innerHTML = hotTopics.map(topic => 
            `<li>${topic.name}: ${topic.count}条</li>`
        ).join('');

        // 标题特征
        const titleFeatures = this.analyzeTitles();
        document.getElementById('titleFeatures').innerHTML = titleFeatures.map(feature => 
            `<li>${feature}</li>`
        ).join('');

        // 互动规律
        const engagementRules = this.analyzeEngagement();
        document.getElementById('engagementRules').innerHTML = engagementRules.map(rule => 
            `<li>${rule}</li>`
        ).join('');
    }

    analyzeHotTopics() {
        const keywords = {
            '理财技巧': ['存钱', '理财', '收益'],
            '金融知识': ['金融', '银行', '利率'],
            '投资教程': ['股票', '基金', '投资'],
            '财经热点': ['政策', '市场', '分析']
        };

        const topics = Object.entries(keywords).map(([name, words]) => ({
            name,
            count: this.notes.filter(note => 
                words.some(word => note.title.includes(word))
            ).length
        }));

        return topics.filter(t => t.count > 0).sort((a, b) => b.count - a.count);
    }

    analyzeTitles() {
        const avgLength = Math.round(
            this.notes.reduce((acc, note) => acc + note.title.length, 0) / this.notes.length
        );

        return [
            `平均标题长度: ${avgLength}字`,
            '最佳区间: 15-25字',
            '常用公式: 数字+动作+价值'
        ];
    }

    analyzeEngagement() {
        const avgEngagement = this.calculateAverage('comments') / this.calculateAverage('likes');

        return [
            `平均互动率: ${(avgEngagement * 100).toFixed(1)}%`,
            '实用性强互动更高',
            '清单型内容收藏率高'
        ];
    }

    showError() {
        document.getElementById('loading').innerHTML = '<p style="color:red;">加载失败,请刷新重试</p>';
    }
}

// 初始化应用
document.addEventListener('DOMContentLoaded', () => {
    new ViralNotesApp();
});
