#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
生成 GitHub Pages HTML 页面
"""
import json
import argparse
from pathlib import Path
from datetime import datetime


def generate_html(input_json, output_html):
    """生成静态 HTML 页面"""

    # 读取数据
    with open(input_json, 'r', encoding='utf-8') as f:
        notes = json.load(f)

    # 计算统计数据
    total_notes = len(notes)
    avg_likes = sum(n['likes'] for n in notes) // total_notes if total_notes > 0 else 0
    avg_collects = sum(n['collects'] for n in notes) // total_notes if total_notes > 0 else 0
    avg_comments = sum(n['comments'] for n in notes) // total_notes if total_notes > 0 else 0

    # 生成页面 (使用上面提供的 HTML 模板)
    html_template = f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>小红书财经爆文分析 - {datetime.now().strftime("%Y-%m-%d")}</title>
    <meta name="description" content="每日分析小红书财经领域低粉爆文,发现爆款选题规律">
    <link rel="stylesheet" href="assets/css/style.css">
</head>
<body>
    <!-- 页面内容 (参考上面的完整 HTML) -->
    <script>
        // 嵌入数据
        const viralNotesData = {json.dumps(notes, ensure_ascii=False)};
    </script>
    <script src="assets/js/app.js"></script>
</body>
</html>"""

    # 保存 HTML
    output_path = Path(output_html)
    output_path.parent.mkdir(parents=True, exist_ok=True)

    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(html_template)

    print(f"✓ HTML 页面已生成: {output_html}")
    print(f"  - 包含 {total_notes} 条笔记")
    print(f"  - 平均点赞: {avg_likes}")
    print(f"  - 平均收藏: {avg_collects}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument('--input', required=True, help='输入 JSON 文件路径')
    parser.add_argument('--output', required=True, help='输出 HTML 文件路径')
    args = parser.parse_args()

    generate_html(args.input, args.output)
